sys_script.script:
(function executeRule(current, previous /*null when async*/) {
  var targetId = current.document_id || current.sysapproval;
  if (!targetId || targetId.nil()) return;
  var app = new GlideRecord('x_2200409_schola_1_scholarship_application');
  if (app.get(targetId)) {
    var approverName = current.approver.name || current.approver.getDisplayValue() || 'Scholarship Manager';
    var commentsText = (current.comments.getJournalEntry(1) + '').trim() || (current.comments + '').trim() || '';
    if (commentsText.indexOf('\n') > -1) {
      commentsText = commentsText.substring(commentsText.indexOf('\n') + 1).trim();
    }
    if (current.state == 'approved') {
      app.application_status = 'approved';
      app.verification_date = new GlideDateTime();
      if (commentsText) {
        app.admin_comments = commentsText + ' (Approved by ' + approverName + ')';
      } else {
        app.admin_comments = 'Approved by ' + approverName + ' after document verification.';
      }
      app.update();
      gs.info('Application ' + app.application_number + ' status updated to approved by manager approval');
    } else if (current.state == 'rejected') {
      app.application_status = 'rejected';
      var rejReason = commentsText || (current.approval_reason + '') || 'Rejected during manager review.';
      app.rejection_reason = rejReason;
      app.admin_comments = 'Rejected by ' + approverName + ': ' + rejReason;
      app.update();
      gs.info('Application ' + app.application_number + ' status updated to rejected by manager rejection');
    }
  }
})(current, previous);
